insert into public.issue_story_summaries(comic_key,series,issue_number,year,publisher,summary,story_title,source,source_url,license,checked_at) select 'tmnt the last ronin|1|2020','TMNT: The Last Ronin','1',2020,'IDW Publishing','{"text": "In a ruined future New York, the surviving Turtle infiltrates the city and attacks the Foot Clan’s fortified headquarters. Carrying his brothers’ weapons and speaking with their imagined voices, he seeks Oroku Hiroto, the grandson of Shredder. A fight with a cybernetic defender sends him falling from the tower before he can reach his target.\n\nWounded and defeated, he retreats into the sewers. The young woman whose motorcycle he took follows him and discovers who he is. After he collapses, he wakes in the care of an older April O’Neil. The final reveal identifies the last surviving Turtle as Michelangelo, transforming the familiar comic-relief brother into a grieving avenger.", "storyTitle": "Wish for Death", "source": "Panel Profits synopsis from published issue coverage", "sourceUrl": "https://www.gamesradar.com/teenage-mutant-ninja-turtles-last-ronin-1-spoilers-reveal-tmnt/", "license": null, "referenceYear": 2020, "credits": {"writers": ["Kevin Eastman", "Tom Waltz"], "pencilers": ["Esau Escorza", "Isaac Escorza"]}}','Wish for Death','Panel Profits synopsis from published issue coverage','https://www.gamesradar.com/teenage-mutant-ninja-turtles-last-ronin-1-spoilers-reveal-tmnt/',null,now() where exists(select 1 from public.sniper_listings where item_id='ebay-v1|257795524079|0') on conflict(comic_key) do update set summary=excluded.summary,source=excluded.source,source_url=excluded.source_url,story_title=excluded.story_title,checked_at=excluded.checked_at;
insert into public.sniper_listing_writeup(key,title,content,written_at,failed_at) select '42ae753666ad018953b63962a6a91381c7db4981','TMNT: The Last Ronin #1 (2020) IDW CGC 10 Gem Mint Comic Book','{"edition": "TMNT: The Last Ronin #1 (2020); confirm the photographed printing and cover", "synopsis": {"intro": "The opening chapter follows a lone Turtle’s failed revenge mission through a future New York controlled by the Foot Clan.", "points": [{"label": "A failed assault", "text": "The survivor carries his brothers’ weapons into an attack on Oroku Hiroto’s tower. Cybernetic opposition forces him into a fall before he can confront his enemy.", "refs": [0]}, {"label": "The survivor revealed", "text": "A young woman finds the wounded Turtle in the sewers. He later wakes with April O’Neil, and the issue reveals that the hardened survivor is Michelangelo.", "refs": [0]}]}, "investment": {"heading": "Why research this opening chapter?", "points": [{"label": "A distinct Michelangelo collecting thesis", "text": "This issue establishes a dramatic change in Michelangelo’s role: the surviving brother becomes a grieving avenger. That gives a character-focused collector a concrete story reason to seek this chapter. It does not establish scarcity or a resale premium.", "refs": [0]}, {"label": "Entry into the Last Ronin story", "text": "The infiltration, failed assault and identity reveal all occur in the opening chapter. A buyer building a Last Ronin collection may value owning that starting point; whether the offered copy is attractive financially still depends on edition-matched completed sales.", "refs": [0]}, {"label": "Do not pay for the wrong printing", "text": "The listing identifies a graded copy of the first issue, but an issue number alone does not prove a first printing or a particular cover. Confirm both from the slab and photographed comic before using another copy’s sale as fair market value. A high numeric grade cannot correct an edition mismatch.", "refs": [1]}]}, "sources": [{"title": "Published issue coverage", "uri": "https://www.gamesradar.com/teenage-mutant-ninja-turtles-last-ronin-1-spoilers-reveal-tmnt/"}, {"title": "IDW issue publication record", "uri": "https://books.apple.com/us/book/teenage-mutant-ninja-turtles-the-last-ronin-1/id1536014941"}], "model": "Codex editorial research", "writtenAt": "2026-10-16T19:46:00Z", "learning": [{"term": "Fair Market Value", "url": "/wiki/terms/fair-market-value-fmv-benchmark", "definition": "Compare the same issue, printing, cover and grade."}]}'::jsonb,now(),null where exists(select 1 from public.sniper_listings where item_id='ebay-v1|257795524079|0') on conflict(key) do update set content=excluded.content,written_at=excluded.written_at,failed_at=null;
